import java.util.*;

class Solution {
    public List<Integer> cheapestTotals(int[] a, int[] b, int k) {
        // heap entries: {total, i, j}, smallest total first
        PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        for (int i = 0; i < Math.min(a.length, k); i++) heap.offer(new int[]{a[i] + b[0], i, 0});
        List<Integer> res = new ArrayList<>();
        while (res.size() < k) {
            int[] top = heap.poll();
            res.add(top[0]);
            int i = top[1], j = top[2];
            if (j + 1 < b.length) heap.offer(new int[]{a[i] + b[j + 1], i, j + 1}); // next in row i
        }
        return res;
    }
}

