class Solution:
    def cheapestTotals(self, a: List[int], b: List[int], k: int) -> List[int]:
        h = [(a[i] + b[0], i, 0) for i in range(min(len(a), k))]
        heapify(h)
        out = []
        while len(out) < k:
            s, i, j = heappop(h)
            out.append(s)
            if j + 1 < len(b): heappush(h, (a[i] + b[j + 1], i, j + 1))
        return out

