function cheapestTotals(a, b, k) {
  const h = [];
  const push = e => { h.push(e); let i = h.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (h[p][0] <= h[i][0]) break; const t = h[p]; h[p] = h[i]; h[i] = t; i = p; } };
  const pop = () => {
    const top = h[0], last = h.pop();
    if (h.length) { h[0] = last; let i = 0; for (;;) { const l = 2 * i + 1, r = l + 1; let m = i; if (l < h.length && h[l][0] < h[m][0]) m = l; if (r < h.length && h[r][0] < h[m][0]) m = r; if (m === i) break; const t = h[i]; h[i] = h[m]; h[m] = t; i = m; } }
    return top;
  };
  for (let i = 0; i < Math.min(a.length, k); i++) push([a[i] + b[0], i, 0]);
  const out = [];
  while (out.length < k) { const [s, i, j] = pop(); out.push(s); if (j + 1 < b.length) push([a[i] + b[j + 1], i, j + 1]); }
  return out;
}
